package report

const reportHTML = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>OpenTelemetry feature parity &amp; corpus coverage</title>
<style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#121a2e;--panel2:#18233b;--line:#2a3856;--text:#eef3ff;--muted:#9baccb;--blue:#62a7ff;--green:#46d39a;--red:#ff7383;--amber:#ffc45b;--gray:#8390a8}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,#1d3763 0,transparent 34%),var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}header,main{max-width:1500px;margin:auto;padding:24px}header{padding-top:42px}h1{font-size:clamp(28px,4vw,48px);line-height:1.08;margin:0 0 10px;letter-spacing:-.035em}h2{font-size:24px;margin:0 0 8px}h3{margin:22px 0 8px}.lede{color:var(--muted);max-width:850px;font-size:16px}.meta{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.pill,.badge{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:999px;padding:3px 9px;background:#0d1528;white-space:nowrap}.panel{background:linear-gradient(145deg,rgba(24,35,59,.96),rgba(15,23,42,.96));border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:20px;box-shadow:0 16px 50px rgba(0,0,0,.2)}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:10px;margin:16px 0}.card{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:13px}.card strong{font-size:21px;display:block}.muted,small{color:var(--muted)}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:15px 0}.filters label{color:var(--muted);font-size:12px}.filters select{display:block;margin-top:4px;min-width:145px}select{background:#0b1427;color:var(--text);border:1px solid var(--line);border-radius:7px;padding:7px}table{border-collapse:collapse;width:100%}th,td{text-align:left;border-bottom:1px solid var(--line);padding:9px;vertical-align:top}th{position:sticky;top:0;background:#121b30;z-index:1;color:#cdd9ef;font-size:12px}.scroll{overflow:auto;max-height:72vh;border:1px solid var(--line);border-radius:9px}.support-supported,.verification-verified,.coverage-exact_golden{color:var(--green);border-color:#27664f}.support-unsupported,.verification-known_gap,.coverage-unavailable{color:var(--red);border-color:#743440}.support-n-a,.verification-not_applicable{color:var(--gray)}.support-unknown,.verification-not_exercised,.coverage-contract_only{color:var(--amber);border-color:#72592c}.group{color:var(--muted);font-size:12px}.evidence{display:block;margin-top:4px;font-size:11px}.matrix-category{color:var(--blue);font-weight:650}.coverage-grid th:first-child,.coverage-grid td:first-child{position:sticky;left:0;background:#121b30}.compare-head{display:flex;gap:9px;flex-wrap:wrap;align-items:end;margin:14px 0}.delta-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}.delta{background:#10192d;border:1px solid var(--line);border-radius:8px;padding:10px}.delta strong{font-size:18px}.trees{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:14px}.tree-side{min-width:0}.trace{border-left:2px solid #365889;padding-left:10px;margin:7px 0}.span{margin:4px 0;padding:6px 8px;background:#10192a;border-radius:6px;overflow-wrap:anywhere}.children{margin-left:18px}.count{color:var(--amber);font-weight:700}details>summary{cursor:pointer;padding:7px}.empty{color:var(--muted);padding:18px;text-align:center}@media(max-width:800px){header,main{padding:16px}.trees{grid-template-columns:1fr}th,td{padding:7px}.scroll{max-height:none}}
</style>
</head>
<body>
<header><h1>OpenTelemetry feature parity<br>&amp; corpus coverage</h1><p class="lede">Upstream Go and Python capability claims are shown separately from what this corpus verifies. Golden availability is coverage evidence, not a claim about language support.</p><div class="meta" id="meta"></div></header>
<main>
<section class="panel"><h2>Coverage overview</h2><p class="muted">Exact golden, portable contract-only, and unavailable coverage are distinct. Counts describe checked-in evidence; they do not report live CI health.</p><div class="cards" id="summary"></div><div class="scroll"><table class="coverage-grid"><thead id="coverage-head"></thead><tbody id="coverage-body"></tbody></table></div><h3>Language signal maturity</h3><div class="cards" id="maturity"></div></section>
<section class="panel"><h2>Feature matrix</h2><p class="muted">Every feature in the pinned OpenTelemetry compliance matrix is included. Corpus badges default to “not exercised” unless a manifest cites concrete evidence.</p><div class="filters"><label>Category<select id="category"><option value="">All categories</option></select></label><label>Language<select id="language"><option value="">Go + Python</option><option value="go">Go</option><option value="python">Python</option></select></label><label>Upstream support<select id="support"><option value="">All states</option><option>supported</option><option>unsupported</option><option value="n/a">n/a</option><option>unknown</option></select></label><label>Corpus verification<select id="verification"><option value="">All states</option><option>verified</option><option>known_gap</option><option>not_exercised</option><option>not_applicable</option></select></label></div><div class="muted" id="feature-count"></div><div class="scroll"><table><thead id="feature-head"></thead><tbody id="feature-body"></tbody></table></div></section>
<section class="panel"><h2>Golden comparison</h2><p class="muted">Deltas are factual right-minus-left differences. Expand trace groups for side-by-side trees; no similarity score or parity judgment is calculated.</p><div class="compare-head"><label>Left implementation<br><select id="left"></select></label><label>Right implementation<br><select id="right"></select></label><label>Scenario<br><select id="scenario"></select></label></div><div id="comparison"></div></section>
</main>
<script type="application/json" id="report-data">__REPORT_DATA__</script>
<script>
const data=JSON.parse(document.getElementById('report-data').textContent);const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const label=v=>String(v).replaceAll('_',' ');const badge=(kind,state)=>'<span class="badge '+kind+'-'+esc(String(state).replaceAll('/','-'))+'">'+esc(label(state))+'</span>';const manifestByProfile=Object.fromEntries(data.manifests.map(m=>[m.profile,m]));const goldenByKey=Object.fromEntries(data.goldens.map(g=>[g.profile+'|'+g.scenario,g]));
function setup(){const source=data.metadata.source;$('meta').innerHTML='<span class="pill">'+data.features.length+' upstream features</span><span class="pill">'+data.goldens.length+' checked-in goldens</span><a class="pill" href="'+esc(source.url)+'">spec '+esc(source.revision.slice(0,12))+'</a><a class="pill" href="'+esc(data.metadata.maturitySource)+'">maturity source</a>';const categories=[...new Set(data.features.map(f=>f.category))];$('category').insertAdjacentHTML('beforeend',categories.map(v=>'<option>'+esc(v)+'</option>').join(''));for(const id of ['category','language','support','verification'])$(id).addEventListener('change',renderFeatures);const options=data.manifests.map(m=>'<option value="'+esc(m.profile)+'">'+esc(m.displayName)+'</option>').join('');$('left').innerHTML=options;$('right').innerHTML=options;$('scenario').innerHTML=data.scenarios.map(s=>'<option>'+esc(s)+'</option>').join('');$('left').value=data.manifests.find(m=>m.profile.includes('aiohttp'))?.profile||data.manifests[0].profile;$('right').value=data.manifests.find(m=>m.profile.includes('django'))?.profile||data.manifests.at(-1).profile;for(const id of ['left','right','scenario'])$(id).addEventListener('change',renderComparison);renderOverview();renderFeatures();renderComparison()}
function renderOverview(){const coverageCounts={};for(const c of data.coverage)coverageCounts[c.state]=(coverageCounts[c.state]||0)+1;const verificationCounts={};for(const byProfile of Object.values(data.verification))for(const v of Object.values(byProfile))verificationCounts[v.state]=(verificationCounts[v.state]||0)+1;const supportCards=['go','python'].map(lang=>{const counts={};for(const f of data.features)counts[f.support[lang]]=(counts[f.support[lang]]||0)+1;return '<div class="card"><strong>'+esc(lang[0].toUpperCase()+lang.slice(1))+' upstream</strong>'+['supported','unsupported','n/a','unknown'].map(s=>'<div>'+badge('support',s)+' '+esc(counts[s]||0)+'</div>').join('')+'</div>'}).join('');$('summary').innerHTML=supportCards+['exact_golden','contract_only','unavailable'].map(s=>'<div class="card"><strong>'+esc(coverageCounts[s]||0)+'</strong>'+badge('coverage',s)+'<small> scenario × implementation cells</small></div>').join('')+['verified','known_gap','not_exercised','not_applicable'].map(s=>'<div class="card"><strong>'+esc(verificationCounts[s]||0)+'</strong>'+badge('verification',s)+'<small> feature claims</small></div>').join('');$('coverage-head').innerHTML='<tr><th>Scenario</th>'+data.manifests.map(m=>'<th>'+esc(m.displayName)+'</th>').join('')+'</tr>';$('coverage-body').innerHTML=data.scenarios.map(s=>'<tr><td>'+esc(s)+'</td>'+data.manifests.map(m=>{const c=data.coverage.find(x=>x.scenario===s&&x.profile===m.profile);return '<td>'+badge('coverage',c.state)+'</td>'}).join('')+'</tr>').join('');$('maturity').innerHTML=Object.entries(data.metadata.maturity).map(([lang,m])=>'<div class="card"><strong>'+esc(lang[0].toUpperCase()+lang.slice(1))+'</strong><div>Traces: '+esc(m.traces)+'</div><div>Metrics: '+esc(m.metrics)+'</div><div>Logs: '+esc(m.logs)+'</div></div>').join('')}
function renderFeatures(){const cat=$('category').value,lang=$('language').value,support=$('support').value,verification=$('verification').value;const langs=lang?[lang]:['go','python'];const manifests=lang?data.manifests.filter(m=>m.language===lang):data.manifests;const rows=data.features.filter(f=>{if(cat&&f.category!==cat)return false;if(support&&!langs.some(l=>f.support[l]===support))return false;if(verification&&!manifests.some(m=>data.verification[f.id][m.profile].state===verification))return false;return true});$('feature-count').textContent=rows.length+' of '+data.features.length+' features';$('feature-head').innerHTML='<tr><th>Category / group</th><th>Feature</th><th>Go upstream</th><th>Python upstream</th>'+data.manifests.map(m=>'<th>'+esc(m.displayName)+' corpus</th>').join('')+'</tr>';$('feature-body').innerHTML=rows.map(f=>'<tr><td><span class="matrix-category">'+esc(f.category)+'</span><div class="group">'+esc(f.group||'—')+'</div></td><td><a href="'+esc(f.source)+'">'+esc(f.name)+'</a>'+(f.optional?'<div class="group">optional: '+esc(f.optional)+'</div>':'')+'</td>'+['go','python'].map(l=>'<td>'+badge('support',f.support[l])+'</td>').join('')+data.manifests.map(m=>{const v=data.verification[f.id][m.profile];return '<td>'+badge('verification',v.state)+(v.evidence?.length?'<span class="evidence">'+v.evidence.map(e=>'<a href="'+esc(e.href)+'">'+esc(e.label)+'</a>').join(' · ')+'</span>':'')+'</td>'}).join('')+'</tr>').join('')}
function renderComparison(){const left=$('left').value,right=$('right').value,scenario=$('scenario').value;if(left===right){$('comparison').innerHTML='<div class="empty">Choose two different implementations.</div>';return}let reverse=false;let cmp=data.comparisons.find(c=>c.leftProfile===left&&c.rightProfile===right&&c.scenario===scenario);if(!cmp){cmp=data.comparisons.find(c=>c.leftProfile===right&&c.rightProfile===left&&c.scenario===scenario);reverse=true}const lg=goldenByKey[left+'|'+scenario],rg=goldenByKey[right+'|'+scenario];if(!cmp){$('comparison').innerHTML='<div class="empty">No comparison metadata.</div>';return}const sign=reverse?-1:1;const delta=v=>sign*v;const mapText=(values,s)=>{const entries=Object.entries(values).map(([k,v])=>[k,s*v]).filter(x=>x[1]);return entries.length?entries.map(([k,v])=>esc(k)+': '+fmt(v)).join('<br>'):'no difference'};const fmt=v=>(v>0?'+':'')+v;const deltas=cmp.available?'<div class="delta-grid"><div class="delta"><small>trace count Δ</small><strong>'+fmt(delta(cmp.traceDelta))+'</strong></div><div class="delta"><small>span count Δ</small><strong>'+fmt(delta(cmp.spanDelta))+'</strong></div><div class="delta"><small>trace-shape group Δ</small><strong>'+fmt(delta(cmp.countDelta))+'</strong></div><div class="delta"><small>scope count Δ</small><div>'+mapText(cmp.scopeDelta,sign)+'</div></div><div class="delta"><small>status count Δ</small><div>'+mapText(cmp.statusDelta,sign)+'</div></div></div>':'<div class="empty">Exact-golden deltas are unavailable because one or both implementations have no checked-in golden for this scenario.</div>';$('comparison').innerHTML=deltas+'<div class="trees"><div class="tree-side"><h3>'+esc(manifestByProfile[left].displayName)+'</h3>'+renderGolden(lg,left)+'</div><div class="tree-side"><h3>'+esc(manifestByProfile[right].displayName)+'</h3>'+renderGolden(rg,right)+'</div></div>'}
function cardinality(g){if(g.exactCount)return '×'+g.count;if(g.cardinality==='one_of')return 'one of '+g.alternatives.length;if(g.minCount===0&&g.maxCount===1)return 'optional';return '×'+g.minCount+'–'+g.maxCount}
function renderGolden(g,profile){if(!g){const c=data.coverage.find(x=>x.profile===profile&&x.scenario===$('scenario').value);return '<div class="empty">'+badge('coverage',c?.state||'unavailable')+'<br>No exact golden tree is checked in.</div>'}const counts=g.exactCounts?g.traceCount+' traces · '+g.spanCount+' spans':'variable trace/span cardinalities';return '<div class="muted">'+counts+' · <a href="'+esc(g.source)+'">golden source</a></div>'+g.traces.map((t,i)=>renderTraceGroup(t,'trace group '+(i+1))).join('')}
function renderTraceGroup(t,title){if(t.alternatives?.length)return '<details><summary><span class="count">'+cardinality(t)+'</span> '+esc(title)+'</summary>'+t.alternatives.map((a,i)=>renderTraceGroup(a,'alternative '+(i+1))).join('')+'</details>';return '<details><summary><span class="count">'+cardinality(t)+'</span> '+esc(title)+' · '+esc(t.coverage)+'</summary><div class="trace">'+t.roots.map(renderSpanGroup).join('')+'</div></details>'}
function renderSpanGroup(g){if(g.alternatives?.length)return '<div class="span"><span class="count">'+cardinality(g)+'</span> alternatives<div class="children">'+g.alternatives.map(renderSpanGroup).join('')+'</div></div>';const s=g.span;return '<div class="span"><span class="count">'+cardinality(g)+'</span> <b>'+esc(s.name||'any name')+'</b><br><small>'+esc(s.scope||'any scope')+' · '+esc(s.kind||'any kind')+' · status '+esc(s.status||'any')+' · HTTP '+esc(s.httpStatus||'any')+'</small>'+(s.children?.length?'<div class="children">'+s.children.map(renderSpanGroup).join('')+'</div>':'')+'</div>'}setup();
</script>
</body></html>`
